-- Inspect the metadata layers of a table (Spark)
SELECT * FROM prod.db.events.snapshots;
SELECT * FROM prod.db.events.manifests;
SELECT file_path, record_count FROM prod.db.events.files;

-- Time travel (Spark SQL; FOR keyword optional)
SELECT * FROM prod.db.events TIMESTAMP AS OF '2026-10-01 00:00:00';
SELECT * FROM prod.db.events VERSION AS OF 10963874102873;

-- Undo a bad load, then trim history
CALL prod.system.rollback_to_snapshot('db.events', 10963874102873);
CALL prod.system.expire_snapshots(table => 'db.events',
  older_than => TIMESTAMP '2026-10-07 00:00:00', retain_last => 10);

ALTER TABLE prod.db.orders ADD COLUMN discount_pct decimal(9,2);
ALTER TABLE prod.db.orders RENAME COLUMN cust_id TO customer_id;
ALTER TABLE prod.db.orders ALTER COLUMN qty TYPE bigint;
ALTER TABLE prod.db.orders DROP COLUMN legacy_flag;

-- Partition evolution: metadata-only, old files untouched
ALTER TABLE prod.db.events ADD PARTITION FIELD hours(event_time);
ALTER TABLE prod.db.events DROP PARTITION FIELD bucket(16, id);

ALTER TABLE prod.db.customers SET TBLPROPERTIES (
  'write.delete.mode' = 'merge-on-read',
  'write.update.mode' = 'copy-on-write');

-- Write-audit-publish with a branch
ALTER TABLE db.table SET TBLPROPERTIES ('write.wap.enabled'='true');
ALTER TABLE db.table CREATE BRANCH `audit-branch` RETAIN 7 DAYS;
-- jobs write with spark.wap.branch = audit-branch; checks run on the branch
CALL catalog.system.fast_forward('db.table', 'main', 'audit-branch');

-- Flink SQL: continuous CDC upsert into an Iceberg v2 table
INSERT INTO iceberg_catalog.db.customers /*+ OPTIONS('upsert-enabled'='true') */
SELECT id, name, email, updated_at FROM kafka_cdc_source;

-- Freeze the training set at model-build time
ALTER TABLE ml.churn_training CREATE TAG `churn-model-v12`;

-- Months later: reproduce the exact training data
SELECT * FROM ml.churn_training VERSION AS OF 'churn-model-v12';

-- Preserve the audited quarter-close state indefinitely
ALTER TABLE prod.finance.risk_positions CREATE TAG `Q1-2026-close` AS OF VERSION 365;

-- Answer the auditor from the preserved state
SELECT * FROM prod.finance.risk_positions VERSION AS OF 'Q1-2026-close';

-- Erasure: logical delete, then make it physical
DELETE FROM prod.crm.customers WHERE customer_id = 42;
CALL catalog.system.expire_snapshots(table => 'prod.crm.customers');
CALL catalog.system.rewrite_data_files(table => 'prod.crm.customers');

-- Test first: Iceberg view of a Hive table, source untouched
CALL spark_catalog.system.snapshot('db.sales', 'db.sales_iceberg_test');
-- Then convert in place (stop all writers first)
CALL spark_catalog.system.migrate('db.sales');

CALL spark_catalog.system.add_files(
  table => 'db.sales_iceberg',
  source_table => 'db.sales_staging');
